        register("r5", "d2", "m2", 10, 5);
        mockMvc.perform(post("/api/releases").contentType("application/json").content("""
                        {"requestId":"r6","model":"m2","fromVersion":"1.0.0","toVersion":"2.0.0","ratio":100}
                        """))
                .andExpect(status().isOk());
